input.command:
cd /home/axel/LeanAlgebraicGeometry-Horizon && python3 - <<'EOF'
import json, collections
d=json.load(open('.archon-horizon/blueprints/Algebraic-Jacobian-Challenge.json'))
N={n['id']:n for n in d['nodes']}
P=[(e['source'],e['target']) for e in d['edges']]
adj=collections.defaultdict(list)
for a,b in P: adj[a].append(b)
tgt='lem:pullback_tensor_map_isiso'
seen=set(); st=[tgt]
while st:
    x=st.pop()
    for y in adj[x]:
        if y not in seen: seen.add(y); st.append(y)
print("descendants:",len(seen))
for x in sorted(seen):
    n=N.get(x,{})
    print(f"  {x:55s} {n.get('lean_status',''):10s} {(n.get('lean_name') or '')[:55]}")
EOF
